create table if not exists public.ce_world_provenance (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.ce_tenants(id) on delete cascade,claim_id uuid references public.ce_world_claims(id) on delete cascade,memory_id uuid references public.ce_intelligence_memories(id) on delete cascade,experience_id uuid references public.ce_intelligence_experiences(id) on delete cascade,source_type text not null,source text not null,source_ref text,source_uri text,source_hash text,collector text,observed_at timestamptz,ingested_at timestamptz not null default now(),freshness_at timestamptz,authority numeric(5,4) not null default .5 check(authority between 0 and 1),reliability numeric(5,4) not null default .5 check(reliability between 0 and 1),independence numeric(5,4) not null default .5 check(independence between 0 and 1),completeness numeric(5,4) not null default .5 check(completeness between 0 and 1),directness numeric(5,4) not null default .5 check(directness between 0 and 1),confidence numeric(5,4) not null default .5 check(confidence between 0 and 1),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.ce_confidence_assessments (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.ce_tenants(id) on delete cascade,claim_id uuid references public.ce_world_claims(id) on delete cascade,subject_key text,predicate text,score numeric(5,4) not null check(score between 0 and 1),calibrated_score numeric(5,4) check(calibrated_score is null or calibrated_score between 0 and 1),status text not null default 'ACTIVE' check(status in ('ACTIVE','SUPERSEDED','RETRACTED')),method text not null,components jsonb not null default '{}'::jsonb,reason text,assessed_at timestamptz not null default now(),supersedes_id uuid references public.ce_confidence_assessments(id) on delete set null);
create index if not exists ce_world_provenance_claim_idx on public.ce_world_provenance(tenant_id,claim_id,ingested_at desc);
create index if not exists ce_world_provenance_source_idx on public.ce_world_provenance(tenant_id,source_type,source,ingested_at desc);
create index if not exists ce_confidence_claim_idx on public.ce_confidence_assessments(tenant_id,claim_id,assessed_at desc);
alter table public.ce_world_provenance enable row level security;alter table public.ce_confidence_assessments enable row level security;revoke all on public.ce_world_provenance,public.ce_confidence_assessments from anon,authenticated;grant all on public.ce_world_provenance,public.ce_confidence_assessments to service_role;